export const columns=['status_pedido','nota_fiscal','pedido_id','data_do_pedido','data_de_faturamento','cnpj_pdv','centro_distribuicao','ean','sku_produto','produto','quantidade_solicitada','quantidade_atendida','quantidade_faturada','quantidade_cancelada','preco_unitario_com_imposto','preco_unitario_sem_imposto','valor_faturado'];
export function record(patch={}){return{status_pedido:'Faturado',nota_fiscal:'123456-ABCDE',pedido_id:'900123',data_do_pedido:'2026-10-28',data_de_faturamento:'2026-10-29',cnpj_pdv:'11222333000181',centro_distribuicao:'Teste',ean:'7890000000001',sku_produto:'TEST',produto:'Produto sintético, apresentação',quantidade_solicitada:'6',quantidade_atendida:'6',quantidade_faturada:'4',quantidade_cancelada:'2',preco_unitario_com_imposto:'10,00',preco_unitario_sem_imposto:'9,00',valor_faturado:'36,00',...patch};}
export function csv(records=[record()],fields=columns,sep=','){const escape=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [fields,...records.map(r=>fields.map(k=>r[k]))].map(r=>r.map(escape).join(sep)).join('\r\n');}
